// Delivery: what came back over the wire. No digest = nothing to settle; say why and stop.
const r = $input.first().json;
const d = r.delivery || {};
const digest = d.reply_digest || d.digest || null;
if (!r.handshake_id) throw new Error('no handshake id in ' + JSON.stringify(r).slice(0, 300));
if (!digest) throw new Error('no delivery digest: dispatch status ' + (d.status || 'none') + (d.reason ? ' — ' + d.reason : ''));
return [{ json: { handshake_id: r.handshake_id, delivery_status: d.status || null, protocol: d.protocol || null, latency_ms: d.latency_ms ?? null, reply_head: d.reply_head || null, evidence: digest, target: r.target || null } }];

// The verdict, with what the settlement needs carried forward.
const j = $input.first().json;
const del = $('Delivery').first().json;
const inp = $('Inputs').first().json;
if (j.ok === false) throw new Error('judge refused: ' + (j.error || JSON.stringify(j).slice(0, 300)));
const decision = j.decision || {};
const composed = (j.receipt && j.receipt.composed) || j.composed || {};
return [{ json: { ...inp, handshake_id: del.handshake_id, evidence: del.evidence, reply_head: del.reply_head, decision_id: decision.id || null, decision_digest: decision.digest || null, decision_anchor: decision.anchor || null, verdict: composed.verdict || composed.ending || composed.tier || null, judge_called: j.judge_called ?? null, model: j.model || null, quota: j.quota || null } }];

// The record: every transaction with its proof and explorer link, the decision, the job.
const legs = ['Seller · approve deposit', 'Buyer · approve + fund', 'Seller · submit', 'Buyer · complete + capture'];
const txs = [];
for (const n of legs) for (const s of ($(n).first().json.sent || [])) txs.push({ leg: n, action: s.action, tx: s.tx, status: s.status, block: s.block, proof: 'https://www.taifoon.io/v1/proof/tx/36927/' + s.tx, scan: 'https://www.taifoon.io/scan/36927/tx/' + s.tx });
const s = $('Settle').first().json;
const v = $('Verdict').first().json;
const complete = txs.find((t) => t.action === 'complete') || null;
return [{ json: { handshake_id: v.handshake_id, decision_id: v.decision_id, decision_digest: v.decision_digest, verdict: v.verdict, jobId: s.jobId, correlator: s.correlator, chainId: 36927, hook: s.hook, token: s.token, price: s.price, premium: s.premium, deposit: s.deposit, evidence: v.evidence, settlement_tx: complete ? complete.tx : null, settlement_proof: complete ? complete.proof : null, transactions: txs, all_mined: txs.length === 6 && txs.every((t) => t.status === 'success') } }];
